"use client";
import { useEffect, useRef, useState } from "react";
import type { PdfPreviewPage } from "@/lib/client/resumeEditor";
import type { PDFWorker } from "pdfjs-dist";
import { LoaderCircle, ZoomIn, ZoomOut } from "lucide-react";
import type { ResumeHighlight } from "@/lib/tiers/resumeTypes";
import type { Rendered } from "@/lib/tiers/resumeRender";

/** The preview consumes exactly the generated bytes used by the download button. */
export function DocumentPreview({ output, version, onReady, highlights, preparedPages }: { output: Rendered; version: string; onReady: (version: string) => void; highlights: ResumeHighlight[]; preparedPages?: PdfPreviewPage[] }) {
  const worker = useRef<PDFWorker | null>(null);
  useEffect(() => () => { worker.current?.destroy(); worker.current = null; }, []);
  const host = useRef<HTMLDivElement>(null);
  const [zoom, setZoom] = useState(false);
  const [error, setError] = useState("");
  const [ready, setReady] = useState("");
  useEffect(() => {
    let cancelled = false;
    let cleanup: (() => void) | undefined;
    const node = host.current;
    if (!node) return;
    async function show() {
      const fragment = document.createDocumentFragment();
      if (output.ext === "pdf" && preparedPages) {
        for (const [index, page] of preparedPages.entries()) {
          const wrapper = document.createElement("div"); wrapper.style.position = "relative";
          const img = document.createElement("img");
          img.src = page.dataUrl; img.alt = `Resume page ${index + 1}`;
          img.style.width = "100%"; img.style.height = "auto"; img.style.display = "block";
          await img.decode();
          if (cancelled) return;
          wrapper.appendChild(img);
          for (const line of highlights) for (const box of line.boxes ?? []) {
            if (box.pageIndex !== index) continue;
            const mark = document.createElement("span"); mark.className = `resume-highlight${line.glow ? " resume-highlight-glow" : ""}`; mark.dataset.lineId = line.id;
            mark.style.left = `${box.x / page.width * 100}%`;
            mark.style.top = `${(page.height - box.y - box.h) / page.height * 100}%`;
            mark.style.width = `${box.w / page.width * 100}%`;
            mark.style.height = `${box.h * 1.3 / page.height * 100}%`;
            wrapper.appendChild(mark);
          }
          fragment.appendChild(wrapper);
        }
      } else if (output.ext === "pdf") {
        const pdfjs = await import("pdfjs-dist");
        pdfjs.GlobalWorkerOptions.workerSrc = "/pdf.worker.min.mjs";
        if (cancelled) return;
        worker.current ??= new pdfjs.PDFWorker();
        const task = pdfjs.getDocument({ data: output.bytes.slice(), worker: worker.current });
        cleanup = () => { void task.destroy().catch(() => {}); };
        const doc = await task.promise;
        for (let n = 1; n <= doc.numPages; n++) {
          if (cancelled) return;
          const page = await doc.getPage(n);
          const natural = page.getViewport({ scale: 1 });
          const density = Math.min(window.devicePixelRatio || 1, 2);
          const scale = Math.min(2, Math.max(0.5, (node!.clientWidth || natural.width) / natural.width * density));
          const viewport = page.getViewport({ scale });
          const canvas = document.createElement("canvas");
          canvas.width = viewport.width; canvas.height = viewport.height;
          canvas.style.width = "100%"; canvas.style.height = "auto";
          canvas.setAttribute("aria-label", `Resume page ${n}`);
          canvas.setAttribute("role", "img");
          const context = canvas.getContext("2d");
          if (!context) throw new Error("Canvas unavailable");
          await page.render({ canvasContext: context, canvas, viewport }).promise;
          if (cancelled) return;
          const wrapper = document.createElement("div");
          wrapper.style.position = "relative";
          wrapper.appendChild(canvas);
          const dimensions = page.getViewport({ scale: 1 });
          for (const line of highlights) for (const box of line.boxes ?? []) {
            if (box.pageIndex !== n - 1) continue;
            const mark = document.createElement("span");
            mark.className = `resume-highlight${line.glow ? " resume-highlight-glow" : ""}`; mark.dataset.lineId = line.id;
            mark.style.left = `${box.x / dimensions.width * 100}%`;
            mark.style.top = `${(dimensions.height - box.y - box.h) / dimensions.height * 100}%`;
            mark.style.width = `${box.w / dimensions.width * 100}%`;
            mark.style.height = `${box.h * 1.3 / dimensions.height * 100}%`;
            wrapper.appendChild(mark);
          }
          fragment.appendChild(wrapper);
        }
      } else if (output.ext === "docx") {
        const mammoth = await import("mammoth");
        const result = await mammoth.convertToHtml({ arrayBuffer: output.bytes.slice().buffer as ArrayBuffer });
        if (cancelled) return;
        // Keep basic Word content; strip links, attributes and active HTML from untrusted documents.
        const parsed = new DOMParser().parseFromString(result.value, "text/html");
        const allowed = new Set(["P", "BR", "STRONG", "EM", "U", "S", "UL", "OL", "LI", "TABLE", "TBODY", "TR", "TD", "TH", "H1", "H2", "H3", "SPAN"]);
        for (const element of [...parsed.body.querySelectorAll("*")]) {
          if (!allowed.has(element.tagName)) {
            if (["SCRIPT", "STYLE", "IFRAME", "OBJECT", "SVG", "MATH", "IMG", "LINK", "META"].includes(element.tagName)) element.remove();
            else element.replaceWith(...Array.from(element.childNodes));
            continue;
          }
          for (const attr of [...element.attributes]) element.removeAttribute(attr.name);
        }
        for (const paragraph of parsed.body.querySelectorAll("p,li")) {
          const highlight = highlights.find((l) => paragraph.textContent?.includes(l.text));
          if (highlight) { paragraph.className = `resume-highlight-text${highlight.glow ? " resume-highlight-glow" : ""}`; (paragraph as HTMLElement).dataset.lineId = highlight.id; }
        }
        fragment.append(...Array.from(parsed.body.childNodes));
      } else {
        if (cancelled) return;
        const pre = document.createElement("pre");
        pre.style.whiteSpace = "pre-wrap"; pre.style.overflowWrap = "anywhere";
        const lines = new TextDecoder().decode(output.bytes).split("\n");
        lines.forEach((text, i) => {
          const span = document.createElement("span");
          const highlight = highlights.find((l) => text.includes(l.text));
          if (highlight) { span.className = `resume-highlight-text${highlight.glow ? " resume-highlight-glow" : ""}`; span.dataset.lineId = highlight.id; }
          span.textContent = text + (i < lines.length - 1 ? "\n" : "");
          pre.appendChild(span);
        });
        fragment.appendChild(pre);
      }
      if (!cancelled) { node!.replaceChildren(fragment); setError(""); setReady(version); onReady(version); }
    }
    show().catch(() => { if (!cancelled) setError("Couldn't render the preview. Try again before downloading."); });
    return () => { cancelled = true; cleanup?.(); };
  }, [output, version, onReady, highlights, zoom, preparedPages]);
  return <div aria-label="Resume preview" data-preview-ready={ready} className="overflow-hidden rounded-xl border border-border bg-surface">
    {ready !== version && !error && <p role="status" className="flex items-center gap-2 p-4 text-sm text-fg-2"><LoaderCircle size={16} className="animate-spin motion-reduce:animate-none" />Rendering your preview</p>}
    {error && <p role="alert" className="p-4 text-sm">{error}</p>}
    {output.ext === "pdf" && <div className="flex justify-end border-b border-border px-2"><button type="button" aria-pressed={zoom} onClick={() => setZoom((value) => !value)} className="inline-flex min-h-11 items-center gap-1.5 px-2 text-xs text-tool-strong">{zoom ? <ZoomOut size={16} /> : <ZoomIn size={16} />}{zoom ? "Fit page" : "Zoom in"}</button></div>}
    <div className="max-w-full overflow-x-auto"><div ref={host} style={zoom && output.ext === "pdf" ? { minWidth: 720 } : undefined} className={output.ext === "pdf" ? "space-y-3" : "resume-document p-5 text-sm leading-relaxed"} /></div>
  </div>;
}
